public class NodeUtil_newQualifiedNameNodeDeclaration_TriageGen1Test {

    private CodingConvention convention;

    @Before
    public void setUp() {
        convention = CodingConvention.SIMPLE;
    }

    @Test
    public void testNewQualifiedNameNodeDeclaration_WithNameIsName() {
        // Case 1: nameNode.isName() is true
        // In Google Closure Compiler, a simple identifier is considered a "name"
        String name = "x";
        Node value = IR.number(1);
        JSDocInfo info = new JSDocInfo();

        Node result = NodeUtil.newQualifiedNameNodeDeclaration(convention, name, value, info);

        assertNotNull(result);
        // When isName() is true, it uses IR.var(nameNode, value)
        // This results in a VAR node with nameNode as first child and value as second
        assertEquals(Token.VAR, result.getType());
        assertEquals(name, result.getFirstChild().getString());
        assertEquals(value, result.getSecondChild());
        assertEquals(info, result.getJSDocInfo());
    }

    @Test
    public void testNewQualifiedNameNodeDeclaration_WithNameIsNotName() {
        // Case 2: nameNode.isName() is false
        // A qualified name like "a.b" is not considered a simple "name" in this context
        String name = "a.b";
        Node value = IR.string("test");
        JSDocInfo info = new JSDocInfo();

        Node result = NodeUtil.newQualifiedNameNodeDeclaration(convention, name, value, info);

        assertNotNull(result);
        // When isName() is false, it uses IR.exprResult(IR.assign(nameNode, value))
        // This results in an EXPR node containing an ASSIGN node
        assertEquals(Token.EXPR, result.getType());

        Node assignNode = result.getFirstChild();
        assertEquals(Token.ASSIGN, assignNode.getType());

        // Verify the name part of the assignment
        assertEquals(name, assignNode.getFirstChild().getString());
        // Verify the value part of the assignment
        assertEquals(value, assignNode.getSecondChild());

        // The method sets JSDoc on the first child of the result (the assign node)
        assertEquals(info, assignNode.getJSDocInfo());
    }

    @Test
    public void testNewQualifiedNameNodeDeclaration_NullValue() {
        // Testing edge case with null value to ensure no crashes
        String name = "x";
        Node value = null;
        JSDocInfo info = new JSDocInfo();

        Node result = NodeUtil.newQualifiedNameNodeDeclaration(convention, name, value, info);

        assertNotNull(result);
        assertEquals(name, result.getFirstChild().getString());
        assertEquals(null, result.getSecondChild());
    }
}
